package main
import("net/http";"time";"fmt";"os";"sync";"encoding/json";"syscall";"io")
func main(){start:=time.Now();url:="http://127.0.0.1:18761/?delay="+os.Args[1]; client:=&http.Client{Transport:&http.Transport{DisableKeepAlives:true},Timeout:9*time.Second};sem:=make(chan struct{},8);call:=func(){sem<-struct{}{};defer func(){<-sem}();r,e:=client.Get(url);if e!=nil{panic(e)};defer r.Body.Close();b,e:=io.ReadAll(r.Body);var p map[string]bool;if e!=nil||r.StatusCode!=200||json.Unmarshal(b,&p)!=nil||!p["ok"]{panic("invalid response")}};var wg sync.WaitGroup;for i:=0;i<22;i++{wg.Add(1);go func(){defer wg.Done();call()}()};call();for i:=0;i<2;i++{wg.Add(1);go func(){defer wg.Done();call()}()};wg.Wait();var r syscall.Rusage;syscall.Getrusage(syscall.RUSAGE_SELF,&r);cpu:=float64(r.Utime.Sec+r.Stime.Sec)*1000+float64(r.Utime.Usec+r.Stime.Usec)/1000;fmt.Printf("{\"ms\":%.6f,\"cpu_ms\":%.6f,\"rss_kib\":%d,\"requests\":25}\n",float64(time.Since(start).Microseconds())/1000,cpu,r.Maxrss)}
